/// Closed lifecycle stage. This V1 document can exist only after generation.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum B4NegativeAncestryWitnessCatalogStageV1 {
    /// Candidate identities measured after seven recipes and eleven bindings.
    PostGenerationDerived,
}

/// Closed producer role of one witness.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum B4NegativeAncestryProducerRoleV1 {
    /// Ordinary source-segment lift.
    Lift,
    /// Lift which proves the assumption receipt selected by resolve.
    AssumptionLift,
    /// Stock join.
    Join,
    /// Stock resolve.
    Resolve,
}

/// Closed logical placement consumed by recursive ancestry replay.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum B4NegativeAncestryLogicalPlacementV1 {
    /// The family assumption receipt.
    AssumptionReceipt,
    /// Non-final ancestry step zero.
    Step0,
    /// Non-final ancestry step two.
    Step2,
    /// Final family receipt.
    FinalReceipt,
}

/// Closed identity of one cryptographically distinct receipt witness.
#[derive(Clone, Copy, Debug, Deserialize, Eq, Ord, PartialEq, PartialOrd, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum B4NegativeAncestryWitnessIdV1 {
    /// Existing case-9 assumption Lift over the canonical statement.
    Case9AssumptionLift,
    /// Existing case-9 final Resolve over the canonical statement.
    Case9FinalResolve,
    /// New assumption Lift over the exact alternate statement.
    AlternateStatementAssumptionLift,
    /// New Lift from the one bound alternate guest ELF.
    AlternateProgramLift,
    /// New final Resolve over the exact alternate statement.
    AlternateStatementFinalResolve,
    /// New final Join over the exact alternate statement.
    AlternateStatementFinalJoin,
    /// New consumer-program Lift with the same assumption recorded twice.
    DuplicateAssumptionLift,
}

/// Exact first public rejection boundary expected after authentication.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct B4NegativeAncestryFirstPublicRejectionV1 {
    /// Stable public rejection class.
    pub class: String,
    /// Stable first rejection stage within that class.
    pub stage: String,
}

#[derive(Clone, Copy)]
enum CompiledRejection {
    ClaimEdge,
    ResolveExplicit,
    ResolveZeroRoot,
    AssumptionInventory,
}

