#[allow(
    clippy::too_many_arguments,
    reason = "each argument is one independently reviewed column of the closed eleven-row table"
)]
const fn slot(
    expanded_row: u16,
    execution_id: &'static str,
    base_family: RecursiveAncestryFamily,
    witness_id: B4NegativeAncestryWitnessIdV1,
    producer_role: B4NegativeAncestryProducerRoleV1,
    logical_placement: B4NegativeAncestryLogicalPlacementV1,
    rejection: CompiledRejection,
) -> CompiledSlot {
    CompiledSlot {
        expanded_row,
        execution_id,
        base_family,
        witness_id,
        producer_role,
        logical_placement,
        rejection,
    }
}

/// Materialize and cross-check the exact eleven-slot compiled layout.
///
/// # Errors
///
/// Returns an error if the closed negative plan or recursive path authority
/// has drifted from the compiled slot contract.
pub fn compiled_negative_ancestry_witness_layout() -> Result<Vec<B4NegativeAncestryWitnessLayoutV1>>
{
    let plan = Eip0045B4NegativePlanV1::canonical()?;
    let executions = plan
        .groups
        .iter()
        .flat_map(|group| group.executions.iter())
        .collect::<Vec<_>>();
    COMPILED_SLOTS
        .iter()
        .map(|compiled| {
            let execution = executions
                .get(usize::from(compiled.expanded_row))
                .context("negative ancestry row is outside the closed plan")?;
            ensure!(
                execution.execution_id == compiled.execution_id,
                "negative ancestry execution ID drifted from the closed plan"
            );
            ensure!(
                execution.execution_surface == B4NegativeExecutionSurface::AncestryReplay
                    && execution.qa_result_code == qa_result_code(compiled.rejection),
                "negative ancestry execution surface or public rejection drifted"
            );
            let logical_consumer_path =
                logical_consumer_path(compiled.base_family, compiled.logical_placement)?;
            let recipe = negative_ancestry_witness_recipe(compiled.execution_id)
                .context("negative ancestry execution is absent from the central recipe table")?;
            Ok(B4NegativeAncestryWitnessLayoutV1 {
                expanded_row: compiled.expanded_row,
                execution_id: compiled.execution_id.to_owned(),
                base_family: compiled.base_family,
                witness_id: compiled.witness_id,
                producer_role: compiled.producer_role,
                logical_placement: compiled.logical_placement,
                recipe,
                logical_consumer_path,
                raw_seal_path: format!(
                    "{B4_NEGATIVE_ANCESTRY_WITNESS_ROOT}/{}.raw-seal.bin",
                    compiled.expanded_row
                ),
                receipt_oracle_path: format!(
                    "{B4_NEGATIVE_ANCESTRY_WITNESS_ROOT}/{}.receipt-oracle.bincode",
                    compiled.expanded_row
                ),
                first_public_rejection: rejection_boundary(compiled.rejection),
            })
        })
        .collect()
}

/// Materialize and validate the exact ordered publication inventory.
///
/// # Errors
///
/// Returns an error if any compiled path is non-portable, non-normalized,
/// absolute, escaping, or duplicated.
pub fn compiled_negative_ancestry_publication_paths()
-> Result<[String; B4_NEGATIVE_ANCESTRY_PUBLICATION_FILE_COUNT]> {
    let mut paths = Vec::with_capacity(B4_NEGATIVE_ANCESTRY_PUBLICATION_FILE_COUNT);
    paths.push(B4_NEGATIVE_ANCESTRY_WITNESS_CATALOG_PATH.to_owned());
    paths.push(B4_NEGATIVE_ANCESTRY_ALTERNATE_GUEST_ELF_PATH.to_owned());
    for slot in compiled_negative_ancestry_witness_layout()? {
        paths.push(slot.raw_seal_path);
        paths.push(slot.receipt_oracle_path);
    }

    let mut unique = BTreeSet::new();
    for path in &paths {
        validate_safe_relative_path(path)
            .with_context(|| format!("invalid negative-ancestry publication path {path}"))?;
        ensure!(
            unique.insert(path.as_str()),
            "duplicate negative-ancestry publication path {path}"
        );
    }
    paths.try_into().map_err(|paths: Vec<String>| {
        anyhow::anyhow!(
            "negative-ancestry publication inventory has {} files instead of {}",
            paths.len(),
            B4_NEGATIVE_ANCESTRY_PUBLICATION_FILE_COUNT
        )
    })
}

const fn qa_result_code(rejection: CompiledRejection) -> B4NegativeQaResultCode {
    match rejection {
        CompiledRejection::ClaimEdge => B4NegativeQaResultCode::B4AncestryClaimEdgeMismatch,
        CompiledRejection::ResolveExplicit => {
            B4NegativeQaResultCode::B4ResolveExplicitSemanticsMismatch
        }
        CompiledRejection::ResolveZeroRoot => {
            B4NegativeQaResultCode::B4ResolveZeroRootSemanticsMismatch
        }
        CompiledRejection::AssumptionInventory => {
            B4NegativeQaResultCode::B4ResolveAssumptionInventoryInvalid
        }
    }
}

fn rejection_boundary(rejection: CompiledRejection) -> B4NegativeAncestryFirstPublicRejectionV1 {
    let stage = match rejection {
        CompiledRejection::ClaimEdge => "claim-edge",
        CompiledRejection::ResolveExplicit => "resolve-explicit-semantics",
        CompiledRejection::ResolveZeroRoot => "resolve-zero-root-semantics",
        CompiledRejection::AssumptionInventory => "resolve-assumption-inventory",
    };
    B4NegativeAncestryFirstPublicRejectionV1 {
        class: "ancestry-replay-mismatch".to_owned(),
        stage: stage.to_owned(),
    }
}

fn logical_consumer_path(
    family: RecursiveAncestryFamily,
    placement: B4NegativeAncestryLogicalPlacementV1,
) -> Result<String> {
    if placement == B4NegativeAncestryLogicalPlacementV1::FinalReceipt {
        return Ok(recursive_ancestry_case_path(
            family,
            RECURSIVE_ANCESTRY_FINAL_SEAL_FILE,
        ));
    }
    let suffix = match placement {
        B4NegativeAncestryLogicalPlacementV1::AssumptionReceipt => {
            "candidate-ancestry-assumption-raw-seal.bin"
        }
        B4NegativeAncestryLogicalPlacementV1::Step0 => "candidate-ancestry-step-00-raw-seal.bin",
        B4NegativeAncestryLogicalPlacementV1::Step2 => "candidate-ancestry-step-02-raw-seal.bin",
        B4NegativeAncestryLogicalPlacementV1::FinalReceipt => unreachable!(),
    };
    recursive_ancestry_expected_auxiliary_paths(family)
        .into_iter()
        .find(|path| path.ends_with(suffix))
        .context("logical ancestry placement is absent from the compiled path authority")
}

