/// Post-generation candidate catalogue. Validation is structural, not authority.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Eip0045B4NegativeAncestryWitnessCatalogV1 {
    /// Exact format discriminator.
    pub format: String,
    /// Exact schema version.
    pub format_version: u8,
    /// Closed post-generation stage.
    pub stage: B4NegativeAncestryWitnessCatalogStageV1,
    /// Exact non-selectable codec used by every direct receipt oracle.
    pub receipt_oracle_codec: String,
    /// Exact campaign negative-plan identity.
    pub negative_plan: B4ContractArtifactIdentityV1,
    /// Exact binary profile-manifest identity.
    pub profile_manifest: B4ContractArtifactIdentityV1,
    /// Exact ELF used only by the two different-program Lift witnesses.
    pub alternate_guest_elf: B4ContractArtifactIdentityV1,
    /// Consumer guest program ID.
    pub consumer_program_id: String,
    /// Image ID later recomputed from `alternateGuestElf`.
    pub alternate_program_id: String,
    /// Profile inner control root.
    pub inner_control_root: String,
    /// Exact ordered eleven-row binding inventory.
    pub entries: Vec<B4NegativeAncestryWitnessEntryV1>,
}

impl Eip0045B4NegativeAncestryWitnessCatalogV1 {
    /// Parse and validate exact RFC 8785 JCS.
    ///
    /// # Errors
    ///
    /// Returns an error for malformed, oversized, duplicate-key,
    /// non-canonical, unknown-field, or semantically drifted input.
    pub fn from_canonical_jcs(source: &[u8]) -> Result<Self> {
        ensure!(
            source.len() <= MAX_CATALOG_JCS_BYTES,
            "negative ancestry witness catalogue exceeds its JCS bound"
        );
        let value = validate_canonical_json_source(source)
            .context("negative ancestry witness catalogue is not exact RFC 8785 JCS")?;
        let catalog: Self =
            serde_json::from_value(value).context("invalid negative ancestry catalogue shape")?;
        catalog.validate()?;
        ensure!(
            catalog.to_canonical_jcs()? == source,
            "negative ancestry witness catalogue does not round-trip byte-exactly"
        );
        Ok(catalog)
    }

    /// Serialize the validated candidate as exact RFC 8785 JCS.
    ///
    /// # Errors
    ///
    /// Returns an error if the candidate is invalid or exceeds its bound.
    pub fn to_canonical_jcs(&self) -> Result<Vec<u8>> {
        self.validate()?;
        let value =
            serde_json::to_value(self).context("cannot serialize negative ancestry catalogue")?;
        let bytes = canonical_json_bytes(&value)?;
        ensure!(
            bytes.len() <= MAX_CATALOG_JCS_BYTES,
            "negative ancestry witness catalogue exceeds its JCS bound"
        );
        Ok(bytes)
    }

    /// Validate the closed structural catalogue without conferring authority.
    ///
    /// # Errors
    ///
    /// Returns an error for any top-level identity, slot, claim, program,
    /// terminal, path, length, digest, encoding, order, or cardinality drift.
    pub fn validate(&self) -> Result<()> {
        ensure!(
            self.format == B4_NEGATIVE_ANCESTRY_WITNESS_CATALOG_FORMAT,
            "wrong negative ancestry witness catalogue format"
        );
        ensure!(
            self.format_version == B4_NEGATIVE_ANCESTRY_WITNESS_CATALOG_VERSION,
            "wrong negative ancestry witness catalogue version"
        );
        ensure!(
            self.stage == B4NegativeAncestryWitnessCatalogStageV1::PostGenerationDerived,
            "wrong negative ancestry witness catalogue stage"
        );
        ensure!(
            self.receipt_oracle_codec == RECEIPT_ORACLE_CODEC_V1,
            "wrong negative ancestry receipt-oracle codec"
        );
        validate_top_level_identity(
            &self.negative_plan,
            B4_NEGATIVE_ANCESTRY_PLAN_PATH,
            B4ContractArtifactEncodingV1::Rfc8785Jcs,
            None,
            "negative plan",
        )?;
        ensure!(
            self.negative_plan.byte_length <= MAX_NEGATIVE_PLAN_BYTES,
            "negative plan exceeds its role-specific byte bound"
        );
        validate_top_level_identity(
            &self.profile_manifest,
            B4_NEGATIVE_ANCESTRY_PROFILE_MANIFEST_PATH,
            B4ContractArtifactEncodingV1::RawBytes,
            Some(MANIFEST_BYTES as u64),
            "profile manifest",
        )?;
        validate_top_level_identity(
            &self.alternate_guest_elf,
            B4_NEGATIVE_ANCESTRY_ALTERNATE_GUEST_ELF_PATH,
            B4ContractArtifactEncodingV1::RawBytes,
            None,
            "alternate guest ELF",
        )?;
        ensure!(
            self.alternate_guest_elf.byte_length <= MAX_ALTERNATE_GUEST_ELF_BYTES,
            "alternate guest ELF exceeds its role-specific byte bound"
        );
        validate_lower_hex_exact(&self.consumer_program_id, DIGEST_BYTES)
            .context("consumer program ID is not exact lowercase hex32")?;
        validate_lower_hex_exact(&self.alternate_program_id, DIGEST_BYTES)
            .context("alternate program ID is not exact lowercase hex32")?;
        ensure!(
            self.alternate_program_id != self.consumer_program_id,
            "alternate program ID equals the consumer program ID"
        );
        validate_lower_hex_exact(&self.inner_control_root, DIGEST_BYTES)
            .context("inner control root is not exact lowercase hex32")?;
        ensure!(
            self.inner_control_root == RISC0_INNER_CONTROL_ROOT_HEX,
            "inner control root differs from the closed profile"
        );

        let layout = compiled_negative_ancestry_witness_layout()?;
        ensure!(
            self.entries.len() == B4_NEGATIVE_ANCESTRY_BINDING_COUNT,
            "negative ancestry witness catalogue must contain exactly eleven row bindings"
        );
        let mut physical_paths = BTreeSet::from([self.alternate_guest_elf.path.as_str()]);
        let mut witness_ids = BTreeSet::new();
        for (entry, expected) in self.entries.iter().zip(&layout) {
            validate_entry(
                entry,
                expected,
                &self.consumer_program_id,
                &self.alternate_program_id,
                &self.inner_control_root,
            )?;
            witness_ids.insert(entry.witness_id);
            ensure!(
                physical_paths.insert(entry.raw_seal.path.as_str())
                    && physical_paths.insert(entry.receipt_oracle.path.as_str()),
                "negative ancestry physical source paths must be globally unique"
            );
        }
        ensure!(
            witness_ids.len() == B4_NEGATIVE_ANCESTRY_DISTINCT_WITNESS_COUNT,
            "negative ancestry row bindings do not select exactly seven witnesses"
        );
        validate_cross_binding_evidence(&self.entries)?;
        Ok(())
    }
}

fn validate_top_level_identity(
    identity: &B4ContractArtifactIdentityV1,
    path: &str,
    encoding: B4ContractArtifactEncodingV1,
    exact_length: Option<u64>,
    label: &str,
) -> Result<()> {
    identity
        .validate()
        .with_context(|| format!("invalid {label} identity"))?;
    ensure!(identity.path == path, "{label} path drifted");
    ensure!(identity.encoding == encoding, "{label} encoding drifted");
    if let Some(exact_length) = exact_length {
        ensure!(
            identity.byte_length == exact_length,
            "{label} length drifted"
        );
    }
    Ok(())
}

#[allow(
    clippy::too_many_lines,
    reason = "the validation sequence mirrors every independently falsifiable catalogue field"
)]
fn validate_entry(
    entry: &B4NegativeAncestryWitnessEntryV1,
    expected: &B4NegativeAncestryWitnessLayoutV1,
    consumer_program_id: &str,
    alternate_program_id: &str,
    inner_control_root: &str,
) -> Result<()> {
    ensure!(
        entry.expanded_row == expected.expanded_row
            && entry.execution_id == expected.execution_id
            && entry.base_family == expected.base_family
            && entry.witness_id == expected.witness_id
            && entry.producer_role == expected.producer_role
            && entry.logical_placement == expected.logical_placement
            && entry.recipe == expected.recipe
            && entry.logical_consumer_path == expected.logical_consumer_path
            && entry.first_public_rejection == expected.first_public_rejection,
        "negative ancestry witness entry drifted from its compiled slot"
    );
    entry
        .raw_seal
        .validate()
        .context("invalid negative ancestry raw-seal identity")?;
    entry
        .receipt_oracle
        .validate()
        .context("invalid negative ancestry receipt-oracle identity")?;
    ensure!(
        entry.raw_seal.path == expected.raw_seal_path
            && entry.raw_seal.encoding == B4ContractArtifactEncodingV1::RawBytes
            && entry.raw_seal.byte_length == PROOF_BYTES as u64,
        "negative ancestry raw-seal path, encoding, or length drifted"
    );
    ensure!(
        entry.receipt_oracle.path == expected.receipt_oracle_path
            && entry.receipt_oracle.encoding == B4ContractArtifactEncodingV1::RawBytes
            && (1..=RECEIPT_ORACLE_MAX_BYTES_U64).contains(&entry.receipt_oracle.byte_length),
        "negative ancestry receipt-oracle path, encoding, or length drifted"
    );
    ensure!(
        entry.raw_seal.path != entry.receipt_oracle.path
            && entry.raw_seal.path != entry.logical_consumer_path
            && entry.receipt_oracle.path != entry.logical_consumer_path,
        "negative ancestry physical source path aliases a logical consumer slot"
    );
    validate_lower_hex_exact(&entry.producer_program_id, DIGEST_BYTES)
        .context("producer program ID is not exact lowercase hex32")?;
    ensure!(
        entry.claim.pre_state_digest == entry.producer_program_id,
        "producer program ID is not bound by the projected claim pre-state"
    );
    let expected_producer_program = if matches!(entry.expanded_row, 147 | 151) {
        alternate_program_id
    } else {
        consumer_program_id
    };
    ensure!(
        entry.producer_program_id == expected_producer_program,
        "producer program differs from the closed row binding"
    );
    validate_lower_hex_exact(&entry.claim_digest, DIGEST_BYTES)
        .context("claim digest is not exact lowercase hex32")?;
    ensure!(
        hex::encode(recursive_ancestry_claim_digest(&entry.claim)?) == entry.claim_digest,
        "claim digest differs from independent RISC Zero recomputation"
    );
    ensure!(
        entry.control_root == inner_control_root,
        "producer control root differs from the catalogued profile root"
    );
    ensure!(
        entry.terminal == expected_terminal(expected.witness_id, expected.producer_role)?,
        "typed producer terminal differs from the compiled role"
    );
    Ok(())
}

fn validate_cross_binding_evidence(entries: &[B4NegativeAncestryWitnessEntryV1]) -> Result<()> {
    let [
        row_141,
        row_142,
        row_143,
        row_145,
        row_147,
        row_148,
        row_150,
        row_151,
        row_152,
        row_153,
        row_154,
    ] = entries
    else {
        bail!("negative ancestry witness relationship check requires eleven row bindings");
    };

    for (left, right) in [
        (row_141, row_142),
        (row_141, row_153),
        (row_145, row_150),
        (row_147, row_151),
    ] {
        ensure!(
            same_evidence_except_paths(left, right),
            "aliased negative ancestry rows do not bind the same receipt evidence"
        );
    }
    ensure!(
        same_claim(row_141, row_143),
        "canonical assumption Lift and final Resolve do not authenticate the same claim"
    );
    for other in [row_148, row_150, row_152] {
        ensure!(
            same_claim(row_145, other),
            "alternate-statement receipts do not authenticate the same claim"
        );
    }
    ensure!(
        !same_claim(row_141, row_145),
        "alternate statement did not change the authenticated claim"
    );
    ensure!(
        !same_claim(row_141, row_154),
        "duplicate-assumption Lift did not change the authenticated claim"
    );
    ensure!(
        !same_claim(row_145, row_154),
        "duplicate-assumption Lift aliases the alternate-statement claim"
    );

    let representatives = [
        row_141, row_143, row_145, row_147, row_148, row_152, row_154,
    ];
    let mut raw_seal_digests = BTreeSet::new();
    let mut receipt_oracle_digests = BTreeSet::new();
    for representative in representatives {
        ensure!(
            raw_seal_digests.insert(representative.raw_seal.sha256.as_str()),
            "distinct witness IDs alias one raw-seal digest"
        );
        ensure!(
            receipt_oracle_digests.insert(representative.receipt_oracle.sha256.as_str()),
            "distinct witness IDs alias one receipt-oracle digest"
        );
    }
    Ok(())
}

fn same_evidence_except_paths(
    left: &B4NegativeAncestryWitnessEntryV1,
    right: &B4NegativeAncestryWitnessEntryV1,
) -> bool {
    same_claim(left, right)
        && left.producer_program_id == right.producer_program_id
        && left.terminal == right.terminal
        && left.control_root == right.control_root
        && same_artifact_bytes(&left.raw_seal, &right.raw_seal)
        && same_artifact_bytes(&left.receipt_oracle, &right.receipt_oracle)
}

fn same_claim(
    left: &B4NegativeAncestryWitnessEntryV1,
    right: &B4NegativeAncestryWitnessEntryV1,
) -> bool {
    left.claim == right.claim && left.claim_digest == right.claim_digest
}

fn same_artifact_bytes(
    left: &B4ContractArtifactIdentityV1,
    right: &B4ContractArtifactIdentityV1,
) -> bool {
    left.byte_length == right.byte_length
        && left.sha256 == right.sha256
        && left.encoding == right.encoding
}

/// Return the sole typed stock terminal admitted for one compiled witness and role.
pub(crate) fn expected_terminal(
    witness_id: B4NegativeAncestryWitnessIdV1,
    role: B4NegativeAncestryProducerRoleV1,
) -> Result<RecursiveAncestryTerminal> {
    let terminal = match (witness_id, role) {
        (
            B4NegativeAncestryWitnessIdV1::DuplicateAssumptionLift,
            B4NegativeAncestryProducerRoleV1::Lift,
        ) => RecursiveAncestryTerminal::Lift {
            segment_po2: 16,
            control_id: RISC0_NORMAL_LIFT_CONTROL_IDS_HEX[1].to_owned(),
        },
        (
            B4NegativeAncestryWitnessIdV1::Case9AssumptionLift
            | B4NegativeAncestryWitnessIdV1::AlternateProgramLift,
            B4NegativeAncestryProducerRoleV1::Lift,
        )
        | (
            B4NegativeAncestryWitnessIdV1::AlternateStatementAssumptionLift,
            B4NegativeAncestryProducerRoleV1::AssumptionLift,
        ) => RecursiveAncestryTerminal::Lift {
            segment_po2: 15,
            control_id: RISC0_NORMAL_LIFT_CONTROL_IDS_HEX[0].to_owned(),
        },
        (
            B4NegativeAncestryWitnessIdV1::AlternateStatementFinalJoin,
            B4NegativeAncestryProducerRoleV1::Join,
        ) => RecursiveAncestryTerminal::Join {
            control_id: RISC0_JOIN_CONTROL_ID_HEX.to_owned(),
        },
        (
            B4NegativeAncestryWitnessIdV1::Case9FinalResolve
            | B4NegativeAncestryWitnessIdV1::AlternateStatementFinalResolve,
            B4NegativeAncestryProducerRoleV1::Resolve,
        ) => RecursiveAncestryTerminal::Resolve {
            control_id: RISC0_RESOLVE_CONTROL_ID_HEX.to_owned(),
        },
        _ => bail!("negative ancestry witness {witness_id:?} cannot use producer role {role:?}"),
    };
    Ok(terminal)
}

