    fn claim(program_id: &str, seed: u8) -> RecursiveAncestryClaim {
        RecursiveAncestryClaim {
            input_digest: format!("{seed:02x}").repeat(DIGEST_BYTES),
            pre_state_digest: program_id.to_owned(),
            post_state_digest: format!("{:02x}", seed.wrapping_add(1)).repeat(DIGEST_BYTES),
            system_exit: 0,
            user_exit: 0,
            output_digest: format!("{:02x}", seed.wrapping_add(2)).repeat(DIGEST_BYTES),
        }
    }

    fn terminal(
        witness_id: B4NegativeAncestryWitnessIdV1,
        role: B4NegativeAncestryProducerRoleV1,
    ) -> RecursiveAncestryTerminal {
        expected_terminal(witness_id, role).unwrap()
    }

    const fn witness_artifact_seed(witness_id: B4NegativeAncestryWitnessIdV1) -> u8 {
        match witness_id {
            B4NegativeAncestryWitnessIdV1::Case9AssumptionLift => 1,
            B4NegativeAncestryWitnessIdV1::Case9FinalResolve => 2,
            B4NegativeAncestryWitnessIdV1::AlternateStatementAssumptionLift => 3,
            B4NegativeAncestryWitnessIdV1::AlternateProgramLift => 4,
            B4NegativeAncestryWitnessIdV1::AlternateStatementFinalResolve => 5,
            B4NegativeAncestryWitnessIdV1::AlternateStatementFinalJoin => 6,
            B4NegativeAncestryWitnessIdV1::DuplicateAssumptionLift => 7,
        }
    }

    const fn witness_claim_seed(witness_id: B4NegativeAncestryWitnessIdV1) -> u8 {
        match witness_id {
            B4NegativeAncestryWitnessIdV1::Case9AssumptionLift
            | B4NegativeAncestryWitnessIdV1::Case9FinalResolve => 1,
            B4NegativeAncestryWitnessIdV1::AlternateStatementAssumptionLift
            | B4NegativeAncestryWitnessIdV1::AlternateStatementFinalResolve
            | B4NegativeAncestryWitnessIdV1::AlternateStatementFinalJoin => 2,
            B4NegativeAncestryWitnessIdV1::AlternateProgramLift => 3,
            B4NegativeAncestryWitnessIdV1::DuplicateAssumptionLift => 4,
        }
    }

    #[test]
    fn duplicate_assumption_lift_uses_po2_16_while_other_lifts_remain_po2_15() {
        assert_eq!(
            expected_terminal(
                B4NegativeAncestryWitnessIdV1::DuplicateAssumptionLift,
                B4NegativeAncestryProducerRoleV1::Lift,
            )
            .unwrap(),
            RecursiveAncestryTerminal::Lift {
                segment_po2: 16,
                control_id: RISC0_NORMAL_LIFT_CONTROL_IDS_HEX[1].to_owned(),
            }
        );

        for (witness_id, role) in [
            (
                B4NegativeAncestryWitnessIdV1::Case9AssumptionLift,
                B4NegativeAncestryProducerRoleV1::Lift,
            ),
            (
                B4NegativeAncestryWitnessIdV1::AlternateStatementAssumptionLift,
                B4NegativeAncestryProducerRoleV1::AssumptionLift,
            ),
            (
                B4NegativeAncestryWitnessIdV1::AlternateProgramLift,
                B4NegativeAncestryProducerRoleV1::Lift,
            ),
        ] {
            assert_eq!(
                expected_terminal(witness_id, role).unwrap(),
                RecursiveAncestryTerminal::Lift {
                    segment_po2: 15,
                    control_id: RISC0_NORMAL_LIFT_CONTROL_IDS_HEX[0].to_owned(),
                }
            );
        }
    }

    #[test]
    fn terminal_dispatch_rejects_every_impossible_witness_role_pair() {
        let witness_ids = [
            B4NegativeAncestryWitnessIdV1::Case9AssumptionLift,
            B4NegativeAncestryWitnessIdV1::Case9FinalResolve,
            B4NegativeAncestryWitnessIdV1::AlternateStatementAssumptionLift,
            B4NegativeAncestryWitnessIdV1::AlternateProgramLift,
            B4NegativeAncestryWitnessIdV1::AlternateStatementFinalResolve,
            B4NegativeAncestryWitnessIdV1::AlternateStatementFinalJoin,
            B4NegativeAncestryWitnessIdV1::DuplicateAssumptionLift,
        ];
        let roles = [
            B4NegativeAncestryProducerRoleV1::Lift,
            B4NegativeAncestryProducerRoleV1::AssumptionLift,
            B4NegativeAncestryProducerRoleV1::Join,
            B4NegativeAncestryProducerRoleV1::Resolve,
        ];
        let valid_pairs = [
            (
                B4NegativeAncestryWitnessIdV1::Case9AssumptionLift,
                B4NegativeAncestryProducerRoleV1::Lift,
            ),
            (
                B4NegativeAncestryWitnessIdV1::Case9FinalResolve,
                B4NegativeAncestryProducerRoleV1::Resolve,
            ),
            (
                B4NegativeAncestryWitnessIdV1::AlternateStatementAssumptionLift,
                B4NegativeAncestryProducerRoleV1::AssumptionLift,
            ),
            (
                B4NegativeAncestryWitnessIdV1::AlternateProgramLift,
                B4NegativeAncestryProducerRoleV1::Lift,
            ),
            (
                B4NegativeAncestryWitnessIdV1::AlternateStatementFinalResolve,
                B4NegativeAncestryProducerRoleV1::Resolve,
            ),
            (
                B4NegativeAncestryWitnessIdV1::AlternateStatementFinalJoin,
                B4NegativeAncestryProducerRoleV1::Join,
            ),
            (
                B4NegativeAncestryWitnessIdV1::DuplicateAssumptionLift,
                B4NegativeAncestryProducerRoleV1::Lift,
            ),
        ];

        for witness_id in witness_ids {
            for role in roles {
                assert_eq!(
                    expected_terminal(witness_id, role).is_ok(),
                    valid_pairs.contains(&(witness_id, role)),
                    "unexpected terminal dispatch for {witness_id:?}/{role:?}"
                );
            }
        }
    }

    fn catalog() -> Eip0045B4NegativeAncestryWitnessCatalogV1 {
        let consumer = "31".repeat(DIGEST_BYTES);
        let alternate = "42".repeat(DIGEST_BYTES);
        let entries = compiled_negative_ancestry_witness_layout()
            .unwrap()
            .into_iter()
            .map(|layout| {
                let producer =
                    if layout.witness_id == B4NegativeAncestryWitnessIdV1::AlternateProgramLift {
                        alternate.clone()
                    } else {
                        consumer.clone()
                    };
                let artifact_seed = witness_artifact_seed(layout.witness_id);
                let claim = claim(&producer, witness_claim_seed(layout.witness_id));
                B4NegativeAncestryWitnessEntryV1 {
                    expanded_row: layout.expanded_row,
                    execution_id: layout.execution_id,
                    base_family: layout.base_family,
                    witness_id: layout.witness_id,
                    producer_role: layout.producer_role,
                    logical_placement: layout.logical_placement,
                    recipe: layout.recipe,
                    logical_consumer_path: layout.logical_consumer_path,
                    first_public_rejection: layout.first_public_rejection,
                    claim_digest: hex::encode(recursive_ancestry_claim_digest(&claim).unwrap()),
                    claim,
                    producer_program_id: producer,
                    terminal: terminal(layout.witness_id, layout.producer_role),
                    control_root: RISC0_INNER_CONTROL_ROOT_HEX.to_owned(),
                    raw_seal: identity(
                        &layout.raw_seal_path,
                        B4ContractArtifactEncodingV1::RawBytes,
                        &vec![artifact_seed; PROOF_BYTES],
                    ),
                    receipt_oracle: identity(
                        &layout.receipt_oracle_path,
                        B4ContractArtifactEncodingV1::RawBytes,
                        &[artifact_seed; 64],
                    ),
                }
            })
            .collect();
        Eip0045B4NegativeAncestryWitnessCatalogV1 {
            format: B4_NEGATIVE_ANCESTRY_WITNESS_CATALOG_FORMAT.to_owned(),
            format_version: B4_NEGATIVE_ANCESTRY_WITNESS_CATALOG_VERSION,
            stage: B4NegativeAncestryWitnessCatalogStageV1::PostGenerationDerived,
            receipt_oracle_codec: RECEIPT_ORACLE_CODEC_V1.to_owned(),
            negative_plan: identity(
                B4_NEGATIVE_ANCESTRY_PLAN_PATH,
                B4ContractArtifactEncodingV1::Rfc8785Jcs,
                b"{\"plan\":1}",
            ),
            profile_manifest: identity(
                B4_NEGATIVE_ANCESTRY_PROFILE_MANIFEST_PATH,
                B4ContractArtifactEncodingV1::RawBytes,
                &vec![0x55; MANIFEST_BYTES],
            ),
            alternate_guest_elf: identity(
                B4_NEGATIVE_ANCESTRY_ALTERNATE_GUEST_ELF_PATH,
                B4ContractArtifactEncodingV1::RawBytes,
                b"synthetic-alternate-guest-elf",
            ),
            consumer_program_id: consumer,
            alternate_program_id: alternate,
            inner_control_root: RISC0_INNER_CONTROL_ROOT_HEX.to_owned(),
            entries,
        }
    }

    #[test]
    fn compiled_layout_is_the_exact_ordered_eleven_row_authority() {
        let layout = compiled_negative_ancestry_witness_layout().unwrap();
        assert_eq!(
            layout
                .iter()
                .map(|slot| slot.expanded_row)
                .collect::<Vec<_>>(),
            [141, 142, 143, 145, 147, 148, 150, 151, 152, 153, 154]
        );
        assert_eq!(
            layout
                .iter()
                .map(|slot| slot.execution_id.as_str())
                .collect::<Vec<_>>(),
            [
                "claim-edge-family-sweep--terminal-join",
                "claim-edge-family-sweep--terminal-resolve-explicit-root",
                "claim-edge-family-sweep--resolve-zero-root-then-join",
                "resolve-explicit-field-sweep--assumption-claim",
                "resolve-explicit-field-sweep--program-id",
                "resolve-explicit-field-sweep--final-claim",
                "resolve-zero-root-field-sweep--assumption-claim",
                "resolve-zero-root-field-sweep--program-id",
                "resolve-zero-root-field-sweep--final-claim",
                "resolve-assumption-inventory-sweep--missing-assumption",
                "resolve-assumption-inventory-sweep--extra-assumption",
            ]
        );
        for excluded in [140, 144, 146, 149, 155] {
            assert!(!layout.iter().any(|slot| slot.expanded_row == excluded));
        }
        assert_eq!(
            layout[0].raw_seal_path,
            "reproduction/negative-ancestry-witnesses/141.raw-seal.bin"
        );
        assert_eq!(
            layout[0].receipt_oracle_path,
            "reproduction/negative-ancestry-witnesses/141.receipt-oracle.bincode"
        );
        for slot in layout {
            assert_ne!(slot.raw_seal_path, slot.receipt_oracle_path);
            assert_ne!(slot.raw_seal_path, slot.logical_consumer_path);
            assert_ne!(slot.receipt_oracle_path, slot.logical_consumer_path);
        }
    }

    #[test]
    fn catalog_round_trips_only_as_strict_bounded_jcs() {
        let catalog = catalog();
        let bytes = catalog.to_canonical_jcs().unwrap();
        assert_eq!(
            Eip0045B4NegativeAncestryWitnessCatalogV1::from_canonical_jcs(&bytes).unwrap(),
            catalog
        );

        let pretty = serde_json::to_vec_pretty(&catalog).unwrap();
        assert!(Eip0045B4NegativeAncestryWitnessCatalogV1::from_canonical_jcs(&pretty).is_err());
        let duplicate = bytes
            .strip_prefix(b"{")
            .map(|tail| {
                [
                    b"{\"format\":\"Eip0045B4NegativeAncestryWitnessCatalogV1\",".as_slice(),
                    tail,
                ]
                .concat()
            })
            .unwrap();
        assert!(Eip0045B4NegativeAncestryWitnessCatalogV1::from_canonical_jcs(&duplicate).is_err());

        let mut unknown = serde_json::to_value(&catalog).unwrap();
        unknown
            .as_object_mut()
            .unwrap()
            .insert("unknown".to_owned(), Value::Bool(true));
        let unknown = canonical_json_bytes(&unknown).unwrap();
        assert!(Eip0045B4NegativeAncestryWitnessCatalogV1::from_canonical_jcs(&unknown).is_err());
    }

    #[test]
    fn catalog_requires_the_exact_frozen_receipt_oracle_codec() {
        const EXPECTED: &str = "bincode-1.3.3-fixint-little-endian-reject-trailing-limit-1048576";

        let value = serde_json::to_value(catalog()).unwrap();
        assert_eq!(
            value
                .get("receiptOracleCodec")
                .and_then(serde_json::Value::as_str),
            Some(EXPECTED)
        );

        let mut missing = value.clone();
        missing
            .as_object_mut()
            .unwrap()
            .remove("receiptOracleCodec");
        let missing = canonical_json_bytes(&missing).unwrap();
        assert!(Eip0045B4NegativeAncestryWitnessCatalogV1::from_canonical_jcs(&missing).is_err());

        let mut wrong = value;
        wrong["receiptOracleCodec"] =
            json!("bincode-1.3.3-varint-big-endian-allow-trailing-limit-unbounded");
        let wrong = canonical_json_bytes(&wrong).unwrap();
        assert!(Eip0045B4NegativeAncestryWitnessCatalogV1::from_canonical_jcs(&wrong).is_err());
    }

