    #[test]
    fn aliases_share_full_evidence_and_related_terminals_share_exact_claims() {
        fn same_evidence_except_paths(
            left: &B4NegativeAncestryWitnessEntryV1,
            right: &B4NegativeAncestryWitnessEntryV1,
        ) {
            assert_eq!(left.claim, right.claim);
            assert_eq!(left.claim_digest, right.claim_digest);
            assert_eq!(left.producer_program_id, right.producer_program_id);
            assert_eq!(left.terminal, right.terminal);
            assert_eq!(left.control_root, right.control_root);
            assert_eq!(left.raw_seal.byte_length, right.raw_seal.byte_length);
            assert_eq!(left.raw_seal.sha256, right.raw_seal.sha256);
            assert_eq!(left.raw_seal.encoding, right.raw_seal.encoding);
            assert_eq!(
                left.receipt_oracle.byte_length,
                right.receipt_oracle.byte_length
            );
            assert_eq!(left.receipt_oracle.sha256, right.receipt_oracle.sha256);
            assert_eq!(left.receipt_oracle.encoding, right.receipt_oracle.encoding);
        }

        let catalog = catalog();
        for (left, right) in [(0, 1), (0, 9), (3, 6), (4, 7)] {
            same_evidence_except_paths(&catalog.entries[left], &catalog.entries[right]);
        }
        assert_eq!(catalog.entries[0].claim, catalog.entries[2].claim);
        assert_eq!(
            catalog.entries[0].claim_digest,
            catalog.entries[2].claim_digest
        );
        for index in [5, 6, 8] {
            assert_eq!(catalog.entries[3].claim, catalog.entries[index].claim);
            assert_eq!(
                catalog.entries[3].claim_digest,
                catalog.entries[index].claim_digest
            );
        }
        assert_ne!(catalog.entries[10].claim, catalog.entries[0].claim);
    }

    #[test]
    fn catalog_rejects_coherent_cross_binding_evidence_drift() {
        let mut alias_claim = catalog();
        alias_claim.entries[1].claim.output_digest = "71".repeat(DIGEST_BYTES);
        alias_claim.entries[1].claim_digest =
            hex::encode(recursive_ancestry_claim_digest(&alias_claim.entries[1].claim).unwrap());
        assert!(alias_claim.validate().is_err());

        let mut alias_seal = catalog();
        alias_seal.entries[9].raw_seal.sha256 = "72".repeat(DIGEST_BYTES);
        assert!(alias_seal.validate().is_err());

        let mut third_program = catalog();
        third_program.entries[7].producer_program_id = "73".repeat(DIGEST_BYTES);
        third_program.entries[7].claim.pre_state_digest = "73".repeat(DIGEST_BYTES);
        third_program.entries[7].claim_digest =
            hex::encode(recursive_ancestry_claim_digest(&third_program.entries[7].claim).unwrap());
        assert!(third_program.validate().is_err());

        let mut final_claim = catalog();
        final_claim.entries[5].claim.output_digest = "74".repeat(DIGEST_BYTES);
        final_claim.entries[5].claim_digest =
            hex::encode(recursive_ancestry_claim_digest(&final_claim.entries[5].claim).unwrap());
        assert!(final_claim.validate().is_err());

        let mut duplicate_is_empty = catalog();
        duplicate_is_empty.entries[10].claim = duplicate_is_empty.entries[0].claim.clone();
        duplicate_is_empty.entries[10].claim_digest =
            duplicate_is_empty.entries[0].claim_digest.clone();
        assert!(duplicate_is_empty.validate().is_err());

        let mut distinct_terminal_same_evidence = catalog();
        distinct_terminal_same_evidence.entries[2].raw_seal.sha256 =
            distinct_terminal_same_evidence.entries[0]
                .raw_seal
                .sha256
                .clone();
        distinct_terminal_same_evidence.entries[2]
            .receipt_oracle
            .sha256 = distinct_terminal_same_evidence.entries[0]
            .receipt_oracle
            .sha256
            .clone();
        assert!(distinct_terminal_same_evidence.validate().is_err());

        let mut duplicate_is_alternate_statement = catalog();
        duplicate_is_alternate_statement.entries[10].claim =
            duplicate_is_alternate_statement.entries[3].claim.clone();
        duplicate_is_alternate_statement.entries[10].claim_digest =
            duplicate_is_alternate_statement.entries[3]
                .claim_digest
                .clone();
        assert!(duplicate_is_alternate_statement.validate().is_err());
    }

