    #[test]
    fn catalog_rejects_missing_extra_reordered_and_semantically_drifted_entries() {
        let mut missing = catalog();
        missing.entries.pop();
        assert!(missing.validate().is_err());

        let mut extra = catalog();
        extra.entries.push(extra.entries[0].clone());
        assert!(extra.validate().is_err());

        let mut reordered = catalog();
        reordered.entries.swap(0, 1);
        assert!(reordered.validate().is_err());

        let mut row = catalog();
        row.entries[0].expanded_row = 140;
        assert!(row.validate().is_err());

        let mut logical = catalog();
        logical.entries[0].logical_consumer_path = logical.entries[0].raw_seal.path.clone();
        assert!(logical.validate().is_err());
    }

    #[test]
    fn catalog_rejects_path_length_digest_program_and_terminal_drift() {
        let mut path = catalog();
        path.entries[0].raw_seal.path = "reproduction/b4nw/999.raw-seal.bin".to_owned();
        assert!(path.validate().is_err());

        let mut length = catalog();
        length.entries[0].raw_seal.byte_length -= 1;
        assert!(length.validate().is_err());

        let mut digest = catalog();
        digest.entries[0].raw_seal.sha256 = "AA".repeat(DIGEST_BYTES);
        assert!(digest.validate().is_err());

        let mut oversized_plan = catalog();
        oversized_plan.negative_plan.byte_length = MAX_NEGATIVE_PLAN_BYTES + 1;
        assert!(oversized_plan.validate().is_err());

        let mut alternate_elf_path = catalog();
        alternate_elf_path.alternate_guest_elf.path =
            "reproduction/negative-ancestry-witnesses/unbound.elf".to_owned();
        assert!(alternate_elf_path.validate().is_err());

        let mut oversized_alternate_elf = catalog();
        oversized_alternate_elf.alternate_guest_elf.byte_length = MAX_ALTERNATE_GUEST_ELF_BYTES + 1;
        assert!(oversized_alternate_elf.validate().is_err());

        let mut claim_digest = catalog();
        claim_digest.entries[0].claim_digest = "01".repeat(DIGEST_BYTES);
        assert!(claim_digest.validate().is_err());

        let mut ordinary_program = catalog();
        ordinary_program.entries[0].producer_program_id = "42".repeat(DIGEST_BYTES);
        ordinary_program.entries[0].claim.pre_state_digest = "42".repeat(DIGEST_BYTES);
        ordinary_program.entries[0].claim_digest = hex::encode(
            recursive_ancestry_claim_digest(&ordinary_program.entries[0].claim).unwrap(),
        );
        assert!(ordinary_program.validate().is_err());

        let mut exceptional_program = catalog();
        exceptional_program.entries[4].producer_program_id =
            exceptional_program.consumer_program_id.clone();
        exceptional_program.entries[4].claim.pre_state_digest =
            exceptional_program.consumer_program_id.clone();
        exceptional_program.entries[4].claim_digest = hex::encode(
            recursive_ancestry_claim_digest(&exceptional_program.entries[4].claim).unwrap(),
        );
        assert!(exceptional_program.validate().is_err());

        let mut terminal = catalog();
        terminal.entries[2].terminal = RecursiveAncestryTerminal::Join {
            control_id: RISC0_JOIN_CONTROL_ID_HEX.to_owned(),
        };
        assert!(terminal.validate().is_err());
    }

    #[cfg(feature = "positive-gate")]
    #[test]
    fn checked_in_schema_accepts_the_rust_catalogue_and_rejects_slot_drift() {
        let schema: Value = serde_json::from_str(include_str!(
            "../finalizer-schema/b4-negative-ancestry-witness-catalog-v1.schema.json"
        ))
        .unwrap();
        let validator = jsonschema::draft202012::options().build(&schema).unwrap();
        let canonical = serde_json::to_value(catalog()).unwrap();
        assert!(validator.validate(&canonical).is_ok());

        let mut wrong_recipe = canonical.clone();
        wrong_recipe["entries"][0]["recipe"] =
            Value::String("reuse-case9-assumption-at-terminal-resolve-step0".to_owned());
        assert!(validator.validate(&wrong_recipe).is_err());

        let mut missing_program = canonical.clone();
        missing_program
            .as_object_mut()
            .unwrap()
            .remove("alternateProgramId");
        assert!(validator.validate(&missing_program).is_err());

        let mut wrong_row_141_terminal = canonical.clone();
        wrong_row_141_terminal["entries"][0]["terminal"] =
            canonical["entries"][10]["terminal"].clone();
        assert!(validator.validate(&wrong_row_141_terminal).is_err());

        let mut wrong_row_154_terminal = canonical.clone();
        wrong_row_154_terminal["entries"][10]["terminal"] =
            canonical["entries"][0]["terminal"].clone();
        assert!(validator.validate(&wrong_row_154_terminal).is_err());

        let mut reordered = canonical;
        reordered["entries"].as_array_mut().unwrap().swap(0, 1);
        assert!(validator.validate(&reordered).is_err());
    }
